import React from 'react';
import {FlatList,View,Text,StyleSheet} from 'react-native';
type Msg={id:string;text:string;mine:boolean};
export default function Chat({msgs}:{msgs:Msg[]}){
  return(<FlatList data={msgs} keyExtractor={m=>m.id} renderItem={({item})=>(<View style={[s.b,item.mine?s.me:s.you]}><Text style={{color:item.mine?'#fff':'#000'}}>{item.text}</Text></View>)} contentContainerStyle={{padding:12}}/>);}
const s=StyleSheet.create({b:{padding:10,borderRadius:14,marginVertical:4,maxWidth:'75%'},me:{alignSelf:'flex-end',backgroundColor:'#0a84ff'},you:{alignSelf:'flex-start',backgroundColor:'#eee'}});
